def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()

def relative_files(root: Path) -> list[Path]:
    return sorted(
        (path for path in root.rglob("*") if path.is_file() and path.name != MANIFEST_NAME),
        key=lambda path: path.relative_to(root).as_posix(),
    )

def build(root: Path, output: Path) -> dict[str, object]:
    root = root.resolve()
    output = output.resolve()
    if not root.is_dir():
        raise RuntimeError(f"runtime root is absent: {root}")
    try:
        output.relative_to(root)
    except ValueError:
        pass
    else:
        raise RuntimeError("payload output must be outside the staged runtime root")

    files = relative_files(root)
    manifest = {
        "schema_version": 1,
        "platform": "win-x64",
        "lock_id": "win-x64-2.0.0",
        "files": [
            {
                "path": path.relative_to(root).as_posix(),
                "size": path.stat().st_size,
                "sha256": sha256(path),
            }
            for path in files
        ],
    }
    manifest_path = root / MANIFEST_NAME
    manifest_path.write_text(
        json.dumps(manifest, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
        newline="\n",
    )
    archive_files = [manifest_path, *files]
    archive_files.sort(key=lambda path: path.relative_to(root).as_posix())

    output.parent.mkdir(parents=True, exist_ok=True)
    if output.exists():
        output.unlink()
    with zipfile.ZipFile(output, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        for path in archive_files:
            relative = PurePosixPath(path.relative_to(root).as_posix())
            info = zipfile.ZipInfo(str(relative), date_time=FIXED_TIME)
            info.compress_type = zipfile.ZIP_DEFLATED
            info.external_attr = 0o100644 << 16
            archive.writestr(info, path.read_bytes(), compress_type=zipfile.ZIP_DEFLATED, compresslevel=9)

    with zipfile.ZipFile(output) as archive:
        bad_member = archive.testzip()
        if bad_member:
            raise RuntimeError(f"payload CRC failed: {bad_member}")
        archived_manifest = json.loads(archive.read(MANIFEST_NAME))
        if archived_manifest != manifest:
            raise RuntimeError("archived payload manifest differs from staging manifest")
        names = set(archive.namelist())
        expected_names = {path.relative_to(root).as_posix() for path in archive_files}
        if names != expected_names:
            raise RuntimeError("payload member set differs from the staged runtime set")

    return {
        "status": "passed",
        "root": str(root),
        "output": str(output),
        "size": output.stat().st_size,
        "sha256": sha256(output),
        "file_count": len(archive_files),
        "manifest": str(manifest_path),
    }

def _terms(text: str) -> list[str]:
    result = {
        token.casefold()
        for token in re.findall(r"[\w.$:/\\-]+", text, flags=re.UNICODE)
        if len(token) >= 2
    }
    for run in re.findall(r"[\u3400-\u9fff]+", text):
        result.add(run)
        result.update(run[index : index + 2] for index in range(max(0, len(run) - 1)))
    return sorted(result, key=lambda value: (-len(value), value))

def _note_documents(markdown_root: Path) -> list[dict[str, Any]]:
    documents = []
    for directory in NOTE_DIRECTORIES:
        for path in sorted((markdown_root / directory).glob("*.md")):
            text = path.read_text(encoding="utf-8")
            title = text.splitlines()[0].removeprefix("# ").strip() if text else path.stem
            tag_match = re.search(r"#类型/[\w\u3400-\u9fff-]+", text)
            documents.append(
                {
                    "title": title,
                    "tag": tag_match.group(0) if tag_match else "",
                    "file": path.relative_to(markdown_root).as_posix(),
                    "content": text,
                    "links": re.findall(r"\[\[([^\]|#]+)", text),
                }
            )
    return documents

def _projection(output: Path) -> tuple[dict[str, Any], str]:
    """Select the richest completed human projection without requiring Markdown."""
    state_path = output / "state.json"
    if state_path.is_file() and json_load(state_path).get("format") == "logseq-db":
        logseq = output / "logseq-db/projection.json"
        if logseq.is_file():
            return json_load(logseq), "logseq-db"
    markdown = output / "markdown/projection.json"
    if markdown.is_file():
        return json_load(markdown), "markdown"
    logseq = output / "logseq-db/projection.json"
    if logseq.is_file():
        return json_load(logseq), "logseq-db"
    raise CkbError("Agent index requires a finalized Markdown or Logseq DB projection")

def _page_documents(
    output: Path,
    projection: dict[str, Any],
    projection_format: str,
    graph: dict[str, Any],
) -> dict[str, dict[str, Any]]:
    """Return readable page documents for either projection.

    Markdown pages are indexed byte-for-byte.  A DB-only build has no page
    files, so the same reviewed source facts are rendered into a compact
    index-only narrative.  This keeps retrieval format-neutral without adding
    another visible knowledge-base projection.
    """
    page_by_id = {page["id"]: page for page in projection.get("pages", [])}
    title_by_id = {page_id: page["title"] for page_id, page in page_by_id.items()}
    owner_by_entity = projection.get("entity_owner_pages", {})
    entity_by_id = {entity["id"]: entity for entity in graph.get("entities", [])}
    owned: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for entity in graph.get("entities", []):
        owner = owner_by_entity.get(entity["id"]) or (entity["id"] if entity["id"] in page_by_id else None)
        if owner in page_by_id:
            owned[owner].append(entity)

    state = json_load(output / "state.json")
    snapshot = state.get("source_snapshot") or {}
    openers = ensure_local_openers(
        output,
        Path(state["repository"]["root"]),
        Path(snapshot["root"]) if snapshot.get("root") else None,
    )
    documents: dict[str, dict[str, Any]] = {}
    for page_id, page in page_by_id.items():
        entity = entity_by_id.get(page_id)
        if projection_format == "markdown":
            relative = Path("markdown") / page["file"]
            content = (output / relative).read_text(encoding="utf-8")
        else:
            relative = Path("logseq-db/normalized.edn")
            lines = [f"# {page['title']}", "", f"标签：{page.get('tag') or ''}", ""]
            if entity:
                overview = " ".join(
                    value.strip()
                    for value in (str(entity.get("meaning_zh", "")), str(entity.get("role_zh", "")))
                    if value.strip()
                )
                if overview:
                    lines.extend([f"> {overview}", ""])
                if entity.get("change_when_zh"):
                    lines.extend(["## 什么时候需要修改", "", str(entity["change_when_zh"]), ""])
                if entity.get("path") and entity.get("range"):
                    lines.extend(
                        [
                            "## 源码位置",
                            "",
                            source_markdown_link(
                                openers,
                                str(entity["path"]),
                                int(entity["range"]["start_line"]),
                                int(entity["range"]["end_line"]),
                            ),
                            "",
                        ]
                    )
            else:
                lines.extend(["> 这是由相关类、函数和辅助实现组成的职责导航页。", ""])
            appendix = [item for item in owned.get(page_id, []) if item.get("classification") == "appendix"]
            if appendix:
                lines.extend(["## 内部细节", ""])
                for item in sorted(appendix, key=lambda value: (value.get("path", ""), value.get("range", {}).get("start_line", 0), value.get("qualified_name", ""))):
                    lines.append(f"- `{item.get('qualified_name') or item.get('name')}`：{item.get('description_zh') or item.get('role_zh') or '承担局部辅助处理。'}")
                lines.append("")
            neighbors = []
            for link in projection.get("links", []):
                if link.get("source") == page_id and link.get("target") in title_by_id:
                    neighbors.append(title_by_id[link["target"]])
                elif link.get("target") == page_id and link.get("source") in title_by_id:
                    neighbors.append(title_by_id[link["source"]])
            if neighbors:
                lines.extend(["## 相关代码", "", *[f"- [[{title}]]" for title in sorted(set(neighbors))], ""])
            content = "\n".join(lines).rstrip() + "\n"
        summary = next(
            (
                line.removeprefix("> ").strip()
                for line in content.splitlines()
                if line.startswith("> ") and line.removeprefix("> ").strip()
            ),
            page["title"],
        )
        source_range = entity.get("range", {}) if entity else {}
        documents[page_id] = {
            "content": content,
            "summary": summary,
            "page_file": relative.as_posix(),
            "source_path": entity.get("path") if entity else None,
            "start_line": source_range.get("start_line"),
            "end_line": source_range.get("end_line"),
        }
    return documents

def build_agent_index(output: Path) -> dict[str, Any]:
    markdown_root = output / "markdown"
    projection, projection_format = _projection(output)
    graph = json_load(output / "graph.json")
    pages = projection.get("pages", [])
    documents = _page_documents(output, projection, projection_format, graph)
    page_by_id = {page["id"]: page for page in pages}
    owner_by_entity = projection.get("entity_owner_pages", {})
    symbols_by_page: dict[str, list[str]] = defaultdict(list)
    for entity in graph.get("entities", []):
        owner = owner_by_entity.get(entity["id"]) or (entity["id"] if entity["id"] in page_by_id else None)
        if owner in page_by_id:
            for value in (entity.get("name"), entity.get("qualified_name")):
                if value:
                    symbols_by_page[owner].append(str(value))
    index = output / "agent-index.sqlite"
    temporary = output / "agent-index.sqlite.tmp"
    temporary.unlink(missing_ok=True)
    connection = sqlite3.connect(temporary)
    try:
        connection.executescript(
            """
            PRAGMA foreign_keys=ON;
            CREATE TABLE meta(key TEXT PRIMARY KEY, value TEXT NOT NULL);
            CREATE TABLE pages(
                page_id TEXT PRIMARY KEY,
                title TEXT NOT NULL UNIQUE,
                page_type TEXT NOT NULL,
                tag TEXT NOT NULL,
                page_file TEXT NOT NULL,
                source_path TEXT,
                start_line INTEGER,
                end_line INTEGER,
                summary TEXT NOT NULL,
                content TEXT NOT NULL,
                token_estimate INTEGER NOT NULL
            );
            CREATE TABLE symbols(
                symbol TEXT NOT NULL,
                qualified_name TEXT NOT NULL,
                owner_page_id TEXT NOT NULL REFERENCES pages(page_id),
                source_path TEXT,
                start_line INTEGER,
                end_line INTEGER
            );
            CREATE INDEX symbols_name ON symbols(symbol COLLATE NOCASE);
            CREATE INDEX symbols_qname ON symbols(qualified_name COLLATE NOCASE);
            CREATE TABLE edges(
                source_page_id TEXT NOT NULL REFERENCES pages(page_id),
                target_page_id TEXT NOT NULL REFERENCES pages(page_id),
                relation TEXT NOT NULL,
                weight REAL NOT NULL,
                PRIMARY KEY(source_page_id,target_page_id,relation)
            );
            CREATE INDEX edges_target ON edges(target_page_id);
            CREATE TABLE terms(
                term TEXT NOT NULL,
                page_id TEXT NOT NULL REFERENCES pages(page_id),
                weight REAL NOT NULL,
                PRIMARY KEY(term,page_id)
            );
            CREATE INDEX terms_term ON terms(term);
            CREATE TABLE notes(
                note_title TEXT PRIMARY KEY,
                tag TEXT NOT NULL,
                note_file TEXT NOT NULL,
                content TEXT NOT NULL,
                token_estimate INTEGER NOT NULL
            );
            CREATE TABLE note_links(
                note_title TEXT NOT NULL REFERENCES notes(note_title),
                page_title TEXT NOT NULL,
                PRIMARY KEY(note_title,page_title)
            );
            CREATE VIRTUAL TABLE page_fts USING fts5(
                page_id UNINDEXED,
                title,
                summary,
                symbols,
                source_path,
                tokenize='trigram'
            );
            CREATE VIRTUAL TABLE note_fts USING fts5(
                note_title UNINDEXED,
                title,
                content,
                tokenize='trigram'
            );
            """
        )
        connection.executemany(
            "INSERT INTO meta(key,value) VALUES(?,?)",
            [
                ("schema_version", str(INDEX_SCHEMA_VERSION)),
                ("status", "ready"),
                ("built_at_utc", utc_now()),
                ("page_count", str(len(pages))),
                ("projection_format", projection_format),
            ],
        )
        entity_by_id = {entity["id"]: entity for entity in graph.get("entities", [])}
        for page in pages:
            document = documents[page["id"]]
            content = document["content"]
            summary = document["summary"]
            source_path = document["source_path"]
            symbols = sorted(set(symbols_by_page.get(page["id"], [])))
            connection.execute(
                "INSERT INTO pages VALUES(?,?,?,?,?,?,?,?,?,?,?)",
                (
                    page["id"],
                    page["title"],
                    page["page_type"],
                    page.get("tag") or "",
                    document["page_file"],
                    source_path,
                    document["start_line"],
                    document["end_line"],
                    summary,
                    content,
                    _tokens(content),
                ),
            )
            connection.execute(
                "INSERT INTO page_fts(page_id,title,summary,symbols,source_path) VALUES(?,?,?,?,?)",
                (page["id"], page["title"], summary, " ".join(symbols), source_path or ""),
            )
            weighted_terms: dict[str, float] = {}
            for value, weight in ((page["title"], 8.0), (" ".join(symbols), 6.0), (summary, 3.0), (source_path or "", 2.0)):
                for term in _terms(value):
                    weighted_terms[term] = max(weighted_terms.get(term, 0.0), weight)
            connection.executemany(
                "INSERT INTO terms(term,page_id,weight) VALUES(?,?,?)",
                [(term, page["id"], weight) for term, weight in sorted(weighted_terms.items())],
            )
        for entity in graph.get("entities", []):
            owner = owner_by_entity.get(entity["id"]) or (entity["id"] if entity["id"] in page_by_id else None)
            if owner not in page_by_id:
                continue
            source_range = entity.get("range", {})
            connection.execute(
                "INSERT INTO symbols VALUES(?,?,?,?,?,?)",
                (
                    str(entity.get("name") or entity.get("qualified_name") or ""),
                    str(entity.get("qualified_name") or entity.get("name") or ""),
                    owner,
                    entity.get("path"),
                    source_range.get("start_line"),
                    source_range.get("end_line"),
                ),
            )
        relation_weight = {"tested-by": 1.4, "calls": 1.3, "invokes": 1.3, "depends-on": 1.2, "uses": 1.1, "contains": 0.8}
        for link in projection.get("links", []):
            if link["source"] not in page_by_id or link["target"] not in page_by_id:
                continue
            connection.execute(
                "INSERT OR REPLACE INTO edges VALUES(?,?,?,?)",
                (link["source"], link["target"], link["type"], relation_weight.get(link["type"], 1.0)),
            )
        for note in _note_documents(markdown_root) if projection_format == "markdown" else []:
            connection.execute(
                "INSERT INTO notes VALUES(?,?,?,?,?)",
                (note["title"], note["tag"], note["file"], note["content"], _tokens(note["content"])),
            )
            connection.execute(
                "INSERT INTO note_fts(note_title,title,content) VALUES(?,?,?)",
                (note["title"], note["title"], note["content"]),
            )
            for title in note["links"]:
                connection.execute("INSERT OR IGNORE INTO note_links VALUES(?,?)", (note["title"], title))
        connection.commit()
        integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
        foreign_keys = connection.execute("PRAGMA foreign_key_check").fetchall()
        if integrity != "ok" or foreign_keys:
            raise CkbError(f"Agent index integrity failed: integrity={integrity}; foreign_keys={foreign_keys}")
    finally:
        connection.close()
    temporary.replace(index)
    return audit_agent_index(output)

def audit_agent_index(output: Path) -> dict[str, Any]:
    index = output / "agent-index.sqlite"
    if not index.is_file():
        return {"schema_version": 1, "status": "failed", "errors": [{"reason": "agent-index-missing"}]}
    projection, projection_format = _projection(output)
    expected_notes = len(_note_documents(output / "markdown")) if projection_format == "markdown" else 0
    connection = sqlite3.connect(f"file:{index.as_posix()}?mode=ro", uri=True)
    try:
        integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
        foreign_keys = connection.execute("PRAGMA foreign_key_check").fetchall()
        counts = {
            "pages": connection.execute("SELECT count(*) FROM pages").fetchone()[0],
            "symbols": connection.execute("SELECT count(*) FROM symbols").fetchone()[0],
            "edges": connection.execute("SELECT count(*) FROM edges").fetchone()[0],
            "terms": connection.execute("SELECT count(*) FROM terms").fetchone()[0],
            "notes": connection.execute("SELECT count(*) FROM notes").fetchone()[0],
        }
        meta = dict(connection.execute("SELECT key,value FROM meta").fetchall())
        forbidden_columns = []
        for table in ("pages", "symbols", "edges", "notes", "meta"):
            for row in connection.execute(f"PRAGMA table_info({table})"):
                if "hash" in str(row[1]).casefold():
                    forbidden_columns.append(f"{table}.{row[1]}")
    finally:
        connection.close()
    errors = []
    if integrity != "ok":
        errors.append({"reason": "sqlite-integrity", "detail": integrity})
    if foreign_keys:
        errors.append({"reason": "foreign-key-errors", "detail": foreign_keys})
    if counts["pages"] != len(projection.get("pages", [])):
        errors.append({"reason": "page-count-mismatch", "actual": counts["pages"], "expected": len(projection.get("pages", []))})
    if counts["notes"] != expected_notes:
        errors.append({"reason": "note-count-mismatch", "actual": counts["notes"], "expected": expected_notes})
    if forbidden_columns:
        errors.append({"reason": "new-index-hash-column-present", "columns": forbidden_columns})
    if meta.get("projection_format") != projection_format:
        errors.append({"reason": "projection-format-mismatch", "actual": meta.get("projection_format"), "expected": projection_format})
    return {
        "schema_version": INDEX_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "path": str(index.resolve()),
        "integrity": integrity,
        "counts": counts,
        "projection_format": projection_format,
        "errors": errors,
    }

def _agent_index_ready(output: Path) -> None:
    index = output / "agent-index.sqlite"
    if not index.is_file():
        raise CkbError("Agent index is missing; run reindex or finalize")
    connection = sqlite3.connect(f"file:{index.as_posix()}?mode=ro", uri=True)
    try:
        meta = dict(connection.execute("SELECT key,value FROM meta").fetchall())
    except sqlite3.DatabaseError as exc:
        raise CkbError(f"Agent index metadata is unavailable: {exc}") from exc
    finally:
        connection.close()
    if meta.get("status") != "ready" or meta.get("schema_version") != str(INDEX_SCHEMA_VERSION):
        raise CkbError(f"Agent index metadata is incompatible: {meta}")

def _fts_query(question: str) -> str | None:
    candidates = [term for term in _terms(question) if len(term) >= 3]
    if not candidates:
        return None
    return " OR ".join('"' + term.replace('"', '""') + '"' for term in candidates[:12])

def _summary_heading_errors(text: str, changed: bool) -> list[str]:
    if not changed:
        return []
    headings = {
        re.sub(r"\s+", "", line.lstrip().lstrip("#").strip())
        for line in text.splitlines()
        if line.lstrip().startswith("#")
    }
    return [heading for heading in _REQUIRED_CHANGE_HEADINGS if heading not in headings]

def sessions_status(output: Path) -> dict[str, Any]:
    directory = output.resolve() / "workspace-meta/sessions"
    sessions = []
    if directory.is_dir():
        for path in sorted(directory.glob("session-*.json")):
            value = json_load(path)
            if value.get("session_id"):
                sessions.append(
                    {
                        "session_id": value["session_id"],
                        "status": value.get("status"),
                        "question": value.get("question"),
                        "started_at_utc": value.get("started_at_utc"),
                        "completed_at_utc": value.get("completed_at_utc"),
                        "record": str(path.resolve()),
                    }
                )
    return {
        "schema_version": SESSION_SCHEMA_VERSION,
        "status": "ready",
        "active": sum(item["status"] == "active" for item in sessions),
        "complete": sum(item["status"] == "complete" for item in sessions),
        "sessions": sessions,
    }

def default_registry_path() -> Path:
    configured = os.environ.get("CKB_AUTOMATION_REGISTRY")
    return Path(configured).expanduser() if configured else Path.home() / ".ckb" / "automation-registry.json"

def _path_key(path: Path | str) -> str:
    value = os.path.abspath(os.path.expanduser(str(path)))
    value = os.path.normcase(os.path.normpath(value))
    return value.replace("\\", "/").rstrip("/")

def _is_within(path: Path | str, root: Path | str) -> bool:
    value = _path_key(path)
    base = _path_key(root)
    return value == base or value.startswith(base + "/")

def _read_registry(path: Path) -> dict[str, Any]:
    if not path.is_file():
        return {"schema_version": AUTOMATION_SCHEMA_VERSION, "projects": []}
    value = json_load(path)
    if value.get("schema_version") in {1, 2} and isinstance(value.get("projects"), list):
        # Earlier registries matched either the repository only or repository
        # plus workspace roots.  Read both through the current hard activation
        # contract; the next registry write upgrades the document atomically.
        value = {
            **value,
            "schema_version": AUTOMATION_SCHEMA_VERSION,
            "projects": [
                {
                    **item,
                    "workspace_roots": list(item.get("workspace_roots") or []),
                    "required_skill": REQUIRED_SKILL,
                    "require_skill_activation": True,
                }
                for item in value["projects"]
            ],
        }
    if value.get("schema_version") != AUTOMATION_SCHEMA_VERSION or not isinstance(value.get("projects"), list):
        raise CkbError(f"unsupported automation registry: {path}")
    for item in value["projects"]:
        item.setdefault("workspace_roots", [])
        item["required_skill"] = REQUIRED_SKILL
        item["require_skill_activation"] = True
    return value

def registry_status(registry_path: Path | None = None) -> dict[str, Any]:
    registry = (registry_path or default_registry_path()).expanduser().resolve()
    value = _read_registry(registry)
    return {
        "schema_version": AUTOMATION_SCHEMA_VERSION,
        "status": "ready",
        "registry": str(registry),
        "project_count": len(value["projects"]),
        "projects": value["projects"],
    }

def _registration_for_event(registry: Path, cwd: Path, harness: str) -> tuple[dict[str, Any], str, str] | None:
    candidates: list[tuple[int, int, dict[str, Any], str, str]] = []
    for item in _read_registry(registry)["projects"]:
        if not item.get("enabled", False) or harness not in item.get("harnesses", []):
            continue
        if _is_within(cwd, item["repo_root"]):
            root = str(item["repo_root"])
            candidates.append((2, len(_path_key(root)), item, "repository", root))
        for workspace_root in item.get("workspace_roots", []):
            if _is_within(cwd, workspace_root):
                candidates.append((1, len(_path_key(workspace_root)), item, "workspace", str(workspace_root)))
    if not candidates:
        return None
    best = max(candidates, key=lambda value: (value[0], value[1]))
    tied = [value for value in candidates if value[:2] == best[:2] and value[2]["registration_id"] != best[2]["registration_id"]]
    if tied:
        raise CkbError(f"automation event cwd matches multiple registrations at the same priority: {cwd}")
    return best[2], best[3], best[4]

def _walk_values(value: Any) -> Iterator[tuple[str | None, Any]]:
    if isinstance(value, dict):
        for key, child in value.items():
            yield str(key), child
            yield from _walk_values(child)
    elif isinstance(value, list):
        for child in value:
            yield None, child
            yield from _walk_values(child)

def _first_scalar(value: Any, keys: set[str]) -> str | None:
    lowered = {key.casefold() for key in keys}
    if isinstance(value, dict):
        for key, child in value.items():
            if str(key).casefold() in lowered and isinstance(child, (str, int)):
                text = str(child).strip()
                if text:
                    return text
        for child in value.values():
            found = _first_scalar(child, keys)
            if found:
                return found
    elif isinstance(value, list):
        for child in value:
            found = _first_scalar(child, keys)
            if found:
                return found
    return None

def _text_content(value: Any) -> str:
    if isinstance(value, str):
        return value
    if isinstance(value, list):
        parts = [_text_content(item) for item in value]
        return "\n".join(item for item in parts if item)
    if isinstance(value, dict):
        direct = value.get("text")
        if isinstance(direct, str):
            return direct
        for key in ("content", "parts", "message", "delta", "info", "properties", "data"):
            if key in value:
                text = _text_content(value[key])
                if text:
                    return text
    return ""

def _event_name(raw: dict[str, Any]) -> str:
    for key in ("hook_event_name", "canonical_type", "event_type", "type"):
        value = raw.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    event = raw.get("event")
    if isinstance(event, dict) and isinstance(event.get("type"), str):
        return event["type"]
    return "unknown"

def _normalized_skill_name(value: Any) -> str:
    text = str(value or "").strip().casefold()
    return text.removeprefix("[").removesuffix("]").lstrip("$/").strip()

def _skill_name(raw: dict[str, Any], tool_name: str | None = None, tool_input: Any = None) -> str | None:
    for key, value in _walk_values(raw):
        if not key or key.casefold() not in _SKILL_METADATA_KEYS:
            continue
        values = value if isinstance(value, list) else [value]
        for item in values:
            if isinstance(item, dict):
                item = item.get("name") or item.get("skill") or item.get("skill_name")
            if _normalized_skill_name(item) == REQUIRED_SKILL:
                return REQUIRED_SKILL
    if str(tool_name or "").casefold() == "skill" and isinstance(tool_input, dict):
        for key in ("skill", "name", "skill_name", "command"):
            if _normalized_skill_name(tool_input.get(key)) == REQUIRED_SKILL:
                return REQUIRED_SKILL
    prompt = str(raw.get("prompt") or raw.get("initial_prompt") or "")
    if _SKILL_PROMPT.search(prompt):
        return REQUIRED_SKILL
    return None

def _extract_paths(value: Any) -> list[str]:
    result: list[str] = []
    for key, child in _walk_values(value):
        if key and key.casefold() in _PATH_KEYS:
            if isinstance(child, str):
                result.append(child)
            elif isinstance(child, list):
                result.extend(str(item) for item in child if isinstance(item, (str, Path)))
        if isinstance(child, str):
            result.extend(match.strip() for match in _PATCH_PATH.findall(child))
    return list(dict.fromkeys(path.strip() for path in result if path.strip()))
